function initials(str){
  if(!str) return '?';
  const parts = str.replace(/[^a-zA-Z. ]/g,'').trim().split(/[\s.]+/).filter(Boolean);
  if(parts.length===0) return '?';
  if(parts.length===1) return parts[0].slice(0,2).toUpperCase();
  return (parts[0][0]+parts[1][0]).toUpperCase();
}
function fmtDate(iso){
  if(!iso) return '—';
  const d = new Date(iso);
  if(isNaN(d)) return iso;
  return d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
}
function toIsoDate(value){
  if(!value) return '';
  const raw = String(value).trim();
  if(!raw) return '';
  const gvizMatch = raw.match(/^Date\((\d{4}),\s*(\d{1,2}),\s*(\d{1,2})/);
  if(gvizMatch){
    const y = Number(gvizMatch[1]);
    const m = Number(gvizMatch[2]) + 1;
    const d = Number(gvizMatch[3]);
    return `${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
  }
  if(/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
  const d = new Date(raw);
  if(isNaN(d.getTime())) return '';
  const y = d.getFullYear();
  const m = String(d.getMonth()+1).padStart(2,'0');
  const day = String(d.getDate()).padStart(2,'0');
  return `${y}-${m}-${day}`;
}
function relTime(iso){
  const now = Date.now(); const t = new Date(iso).getTime();
  const diff = Math.max(0, now-t);
  const min=60000,hr=3600000,day=86400000;
  if(diff<hr) return Math.max(1,Math.round(diff/min))+'m ago';
  if(diff<day) return Math.round(diff/hr)+'h ago';
  return Math.round(diff/day)+'d ago';
}
function fmtDuration(ms){
  if(ms==null) return '—';
  const day=86400000, hr=3600000;
  if(ms < hr) return Math.max(1,Math.round(ms/60000))+'m';
  if(ms < day) return (ms/hr).toFixed(1)+'h';
  return (ms/day).toFixed(1)+'d';
}
function today0(){ const d=new Date(); d.setHours(0,0,0,0); return d; }
function isOverdue(estDate, status){
  if(!estDate || status==='Done') return false;
  const d = new Date(estDate);
  return d < today0();
}
function uid(prefix){ return prefix+'-'+Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
