let distBoard = 'pd';

function computeBacktrackingCount(pd, uxr){
  const pdOrder = PD_STATUSES.map(s=>s.id);
  const uxrOrder = UXR_STATUSES.map(s=>s.id);
  function countFor(tasks, order){
    let n = 0;
    tasks.forEach(t=>{
      for(let i=1;i<t.history.length;i++){
        const prev = t.history[i-1], h = t.history[i];
        const fi = order.indexOf(prev.status), ti = order.indexOf(h.status);
        if(fi>=0 && ti>=0 && ti<fi){ n++; break; }
      }
    });
    return n;
  }
  return countFor(pd, pdOrder) + countFor(uxr, uxrOrder);
}

const UTILITY_CAPACITY_PER_PERSON = 3;
function computeUtility(pd, uxr){
  const byPerson = computeWorkload(pd, uxr);
  const names = Object.keys(byPerson).filter(n=>n!=='Unassigned');
  if(names.length===0) return {pct:0, people:0, openTasks:0};
  const openTasks = names.reduce((s,n)=>s+byPerson[n].total,0);
  const pct = Math.round((openTasks/(names.length*UTILITY_CAPACITY_PER_PERSON))*100);
  return {pct, people:names.length, openTasks};
}

let dashboardAppFilter = '';

function renderDashboard(){
  const appSel = document.getElementById('dashboardAppFilter');
  if(appSel.options.length<=1){
    appSel.innerHTML = `<option value="">All apps</option>` + DATA.apps.map(a=>`<option value="${escAttr(a.name)}">${escapeHtml(a.name)}</option>`).join('');
  }
  appSel.value = dashboardAppFilter;

  let pd = getAllPdTasks(); let uxr = getAllUxrTasks();
  if(dashboardAppFilter){
    pd = pd.filter(t=>t.appName===dashboardAppFilter);
    uxr = uxr.filter(t=>uxrTaskAppName(t)===dashboardAppFilter);
  }

  const kpiRow = document.getElementById('kpiRow');
  const inProgress = pd.filter(t=>t.status!=='Not Started' && t.status!=='Done').length;
  const overdue = pd.filter(t=>isOverdue(t.estDate, t.status)).length + uxr.filter(t=>isOverdue(t.estDate,t.status)).length;
  const backtracking = computeBacktrackingCount(pd, uxr);
  const util = computeUtility(pd, uxr);

  kpiRow.innerHTML = `
    <div class="kpi"><div class="label">Total tasks</div><div class="num">${pd.length+uxr.length}</div><div class="sub">${pd.length} PD · ${uxr.length} UXR</div></div>
    <div class="kpi"><div class="label">In progress</div><div class="num">${inProgress}</div><div class="sub">PD tasks past "Not Started"</div></div>
    <div class="kpi"><div class="label">Overdue</div><div class="num" style="color:${overdue?'var(--danger)':'inherit'}">${overdue}</div><div class="sub ${overdue?'warn':''}">Past estimated date, not done</div></div>
    <div class="kpi"><div class="label">Backtracking</div><div class="num" style="color:${backtracking?'var(--danger)':'inherit'}">${backtracking}</div><div class="sub ${backtracking?'warn':''}">Tasks sent back to an earlier status</div></div>
    <div class="kpi"><div class="label">Utility</div><div class="num" style="color:${util.pct>100?'var(--danger)':'inherit'}">${util.pct}%</div><div class="sub">${util.openTasks} open tasks across ${util.people} people · est. at ${UTILITY_CAPACITY_PER_PERSON}/person</div></div>
  `;

  document.getElementById('appBreakdownCard').style.display = dashboardAppFilter ? 'none' : 'block';
  if(!dashboardAppFilter) renderAppBreakdown();

  renderTaskDist(pd, uxr);
  renderFeed(pd, uxr);
  renderTimeTable(pd, uxr);
  workloadData = {pd, uxr};
  renderWorkloadChart();
  renderDashboardPatterns(pd, uxr);
}

function renderAppBreakdown(){
  const tbody = document.querySelector('#appBreakdownTable tbody');
  const allPd = getAllPdTasks(); const allUxr = getAllUxrTasks();
  const rows = DATA.apps.map(app=>{
    const pdTasks = allPd.filter(t=>t.appName===app.name);
    const uxrTasks = allUxr.filter(t=>uxrTaskAppName(t)===app.name);
    const total = pdTasks.length + uxrTasks.length;
    const inProgress = pdTasks.filter(t=>t.status!=='Not Started' && t.status!=='Done').length;
    const overdue = pdTasks.filter(t=>isOverdue(t.estDate,t.status)).length + uxrTasks.filter(t=>isOverdue(t.estDate,t.status)).length;
    const backtracking = computeBacktrackingCount(pdTasks, uxrTasks);
    return {name:app.name, total, inProgress, overdue, backtracking};
  }).sort((a,b)=>b.total-a.total);

  if(rows.every(r=>r.total===0)){
    tbody.innerHTML = `<tr><td colspan="5"><div class="empty-state" style="padding:14px 0"><p>No tasks tracked yet.</p></div></td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map(r=>`
    <tr class="app-breakdown-row" data-app="${escAttr(r.name)}" style="cursor:pointer;${r.total===0?'opacity:.45':''}">
      <td style="font-weight:700">${escapeHtml(r.name)}</td>
      <td class="mono">${r.total}</td>
      <td class="mono">${r.inProgress}</td>
      <td class="mono" style="${r.overdue?'color:var(--danger);font-weight:700':''}">${r.overdue}</td>
      <td class="mono" style="${r.backtracking?'color:var(--danger);font-weight:700':''}">${r.backtracking}</td>
    </tr>`).join('');

  tbody.querySelectorAll('.app-breakdown-row').forEach(row=>{
    row.addEventListener('click', ()=>{
      dashboardAppFilter = row.dataset.app;
      document.getElementById('dashClearFilterBtn').style.display = 'inline-flex';
      renderDashboard();
    });
  });
}

document.getElementById('dashboardAppFilter').addEventListener('change', e=>{
  dashboardAppFilter = e.target.value;
  document.getElementById('dashClearFilterBtn').style.display = dashboardAppFilter ? 'inline-flex' : 'none';
  renderDashboard();
});
document.getElementById('dashClearFilterBtn').addEventListener('click', ()=>{
  dashboardAppFilter = '';
  document.getElementById('dashboardAppFilter').value = '';
  document.getElementById('dashClearFilterBtn').style.display = 'none';
  renderDashboard();
});

