function renderTaskDist(pd, uxr){
  const tasks = distBoard==='pd' ? pd : uxr;
  const statuses = distBoard==='pd' ? PD_STATUSES : UXR_STATUSES;
  document.getElementById('distSub').textContent = distBoard==='pd'
    ? 'Across all Product Design tasks currently tracked'
    : 'Across all UX Research tasks currently tracked';
  renderDist('taskDist', tasks, statuses);
}
document.getElementById('distToggle').addEventListener('click', e=>{
  const b = e.target.closest('.pill-toggle-btn'); if(!b) return;
  distBoard = b.dataset.board;
  document.querySelectorAll('#distToggle .pill-toggle-btn').forEach(x=>x.classList.toggle('active', x===b));
  renderTaskDist(getAllPdTasks(), getAllUxrTasks());
});

function renderDist(elId, tasks, statuses){
  const el = document.getElementById(elId);
  const max = Math.max(1, ...statuses.map(s=>tasks.filter(t=>t.status===s.id).length));
  el.innerHTML = statuses.map(s=>{
    const count = tasks.filter(t=>t.status===s.id).length;
    const v = colorVars(s.color);
    const pct = Math.round((count/max)*100);
    return `<div class="dist-row">
      <div class="dlabel">${s.id}</div>
      <div class="dist-track"><div class="dist-fill" style="width:${pct}%;background:${v.bd}"></div></div>
      <div class="dcount">${count}</div>
    </div>`;
  }).join('');
}

function renderFeed(pd, uxr){
  const el = document.getElementById('activityFeed');
  const events = [];
  pd.forEach(t=>t.history.forEach(h=>{ if(!h.isSeed) events.push({title:t.title, status:h.status, at:h.enteredAt, board:'PD'}); }));
  uxr.forEach(t=>t.history.forEach(h=>{ if(!h.isSeed) events.push({title:t.title, status:h.status, at:h.enteredAt, board:'UXR'}); }));
  events.sort((a,b)=>new Date(b.at)-new Date(a.at));
  if(events.length===0){
    el.innerHTML = `<div class="empty-state" style="padding:20px 0"><p>No status changes recorded yet. Drag a card on either board to start tracking movement.</p></div>`;
    return;
  }
  el.innerHTML = events.map(e=>`
    <div class="feed-item">
      <div class="feed-dot"></div>
      <div>
        <div class="feed-text"><b>${escapeHtml(e.title)}</b> moved to <b>${escapeHtml(e.status)}</b> <span class="tag" style="margin-left:2px">${e.board}</span></div>
        <div class="feed-time">${relTime(e.at)}</div>
      </div>
    </div>`).join('');
}

let timeBoard = 'pd';
let timeTableData = {pd:[], uxr:[]};

function renderTimeTable(pd, uxr){
  timeTableData = {pd, uxr};
  renderTimeTableBoard();
}
function renderTimeTableBoard(){
  const tbody = document.querySelector('#timeTable tbody');
  const tasks = timeBoard==='pd' ? timeTableData.pd : timeTableData.uxr;
  const statuses = timeBoard==='pd' ? PD_STATUSES : UXR_STATUSES;
  document.getElementById('timeSub').textContent = timeBoard==='pd'
    ? 'Average time a PD task spends in each column'
    : 'Average time a UXR task spends in each column';
  tbody.innerHTML = statuses.map(s=>{
    let durations = []; let currentlyIn = 0;
    tasks.forEach(t=>{
      t.history.forEach(h=>{
        if(h.status!==s.id) return;
        if(h.exitedAt){ durations.push(new Date(h.exitedAt)-new Date(h.enteredAt)); }
        else { currentlyIn++; }
      });
    });
    const avg = durations.length ? durations.reduce((a,b)=>a+b,0)/durations.length : null;
    const v = colorVars(s.color);
    return `<tr>
      <td><span class="badge" style="background:${v.bg};border-color:${v.bd};color:${v.tx}"><span class="dot" style="background:${v.bd}"></span>${s.id}</span></td>
      <td class="mono">${avg==null?'—':fmtDuration(avg)}</td>
      <td>${currentlyIn} task${currentlyIn===1?'':'s'}</td>
    </tr>`;
  }).join('');
}
document.getElementById('timeToggle').addEventListener('click', e=>{
  const b = e.target.closest('.pill-toggle-btn'); if(!b) return;
  timeBoard = b.dataset.board;
  document.querySelectorAll('#timeToggle .pill-toggle-btn').forEach(x=>x.classList.toggle('active', x===b));
  renderTimeTableBoard();
});

/* ---------- workload donut chart ---------- */
let workloadMode = 'user';
let statusBoardFilter = 'pd';
let workloadData = {pd:[], uxr:[]};

function computeWorkload(pd, uxr){
  const byPerson = {};
  function addTasks(tasks){
    tasks.forEach(t=>{
      if(t.status==='Done') return;
      const names = splitPeople(t.productDesigner||t.assignee);
      (names.length?names:['Unassigned']).forEach(n=>{
        byPerson[n] = byPerson[n] || {total:0, statusCounts:{}};
        byPerson[n].total++;
        byPerson[n].statusCounts[t.status] = (byPerson[n].statusCounts[t.status]||0)+1;
      });
    });
  }
  addTasks(pd); addTasks(uxr);
  return byPerson;
}
function computeWorkloadByStatus(pd, uxr){
  const byStatus = {};
  function addTasks(tasks, board){
    tasks.forEach(t=>{
      if(t.status==='Done') return;
      const key = board+'·'+t.status;
      byStatus[key] = byStatus[key] || {total:0, board, statusId:t.status, personCounts:{}};
      byStatus[key].total++;
      const names = splitPeople(t.productDesigner||t.assignee);
      (names.length?names:['Unassigned']).forEach(n=>{ byStatus[key].personCounts[n] = (byStatus[key].personCounts[n]||0)+1; });
    });
  }
  addTasks(pd, 'PD'); addTasks(uxr, 'UXR');
  return byStatus;
}
function polarToCartesian(cx,cy,r,angleDeg){
  const a = (angleDeg-90) * Math.PI/180;
  return {x: cx + r*Math.cos(a), y: cy + r*Math.sin(a)};
}
function donutSlicePath(cx,cy,rOuter,rInner,startAngle,endAngle){
  const startOuter = polarToCartesian(cx,cy,rOuter,endAngle);
  const endOuter = polarToCartesian(cx,cy,rOuter,startAngle);
  const startInner = polarToCartesian(cx,cy,rInner,endAngle);
  const endInner = polarToCartesian(cx,cy,rInner,startAngle);
  const largeArc = (endAngle-startAngle) <= 180 ? 0 : 1;
  return `M ${startOuter.x.toFixed(2)} ${startOuter.y.toFixed(2)} A ${rOuter} ${rOuter} 0 ${largeArc} 0 ${endOuter.x.toFixed(2)} ${endOuter.y.toFixed(2)} L ${endInner.x.toFixed(2)} ${endInner.y.toFixed(2)} A ${rInner} ${rInner} 0 ${largeArc} 1 ${startInner.x.toFixed(2)} ${startInner.y.toFixed(2)} Z`;
}
function personColor(i){
  const hue = (162 + i*137.508) % 360;
  return `hsl(${hue.toFixed(0)} 60% 52%)`;
}
function showChartTooltip(html, x, y){
  const tt = document.getElementById('chartTooltip');
  tt.innerHTML = html;
  const left = Math.min(x+16, window.innerWidth-220);
  tt.style.left = left+'px';
  tt.style.top = (y+16)+'px';
  tt.classList.add('show');
}
function hideChartTooltip(){ document.getElementById('chartTooltip').classList.remove('show'); }

function buildUserEntries(pd, uxr){
  const byPerson = computeWorkload(pd, uxr);
  return Object.entries(byPerson).sort((a,b)=>b[1].total-a[1].total).map(([name,data],i)=>({
    label:name, sub:null, total:data.total, color:personColor(i), breakdown:data.statusCounts
  }));
}
function buildStatusEntries(pd, uxr, board){
  const byStatus = computeWorkloadByStatus(pd, uxr);
  const boardLabel = board.toUpperCase();
  return Object.values(byStatus)
    .filter(s=>s.board===boardLabel)
    .sort((a,b)=>b.total-a.total)
    .map(s=>{
      const list = s.board==='PD' ? PD_STATUSES : UXR_STATUSES;
      const v = colorVars(statusDef(list, s.statusId).color);
      return { label:s.statusId, sub:null, total:s.total, color:v.bd, breakdown:s.personCounts };
    });
}

function renderWorkloadChart(){
  document.getElementById('statusBoardToggle').style.display = workloadMode==='status' ? 'flex' : 'none';
  const entries = workloadMode==='user'
    ? buildUserEntries(workloadData.pd, workloadData.uxr)
    : buildStatusEntries(workloadData.pd, workloadData.uxr, statusBoardFilter);
  document.getElementById('workloadSub').textContent = workloadMode==='user'
    ? 'Open tasks per person, across the PD and UXR boards — hover a slice for the status breakdown'
    : `Open ${statusBoardFilter.toUpperCase()} tasks per status — hover a slice for who's holding them`;
  drawDonut(entries);
}

function drawDonut(entries){
  const svg = document.getElementById('workloadDonut');
  const legend = document.getElementById('workloadLegend');
  const total = entries.reduce((s,e)=>s+e.total,0);

  if(entries.length===0){
    svg.innerHTML = `<circle cx="90" cy="90" r="62" fill="none" stroke="var(--surface-2)" stroke-width="26"/>`;
    legend.innerHTML = `<div class="empty-state" style="padding:10px 0"><p>Nothing open right now.</p></div>`;
    return;
  }

  const cx=90, cy=90, rOuter=76, rInner=48;
  let cursor = 0;
  let paths = '';
  if(entries.length===1){
    paths = `<circle cx="${cx}" cy="${cy}" r="${(rOuter+rInner)/2}" fill="none" stroke="${entries[0].color}" stroke-width="${rOuter-rInner}" data-idx="0"></circle>`;
  } else {
    entries.forEach((e,i)=>{
      const frac = e.total/total;
      const startAngle = cursor*360;
      const endAngle = (cursor+frac)*360;
      cursor += frac;
      paths += `<path d="${donutSlicePath(cx,cy,rOuter,rInner,startAngle,endAngle)}" fill="${e.color}" data-idx="${i}"></path>`;
    });
  }
  svg.innerHTML = paths + `
    <text x="90" y="86" text-anchor="middle" class="donut-center-total">${total}</text>
    <text x="90" y="101" text-anchor="middle" class="donut-center-label">OPEN TASKS</text>
  `;

  legend.innerHTML = entries.map((e,i)=>`
    <div class="donut-legend-row" data-idx="${i}">
      <span class="dl-sw" style="background:${e.color}"></span>
      <span class="dl-name">${e.sub?`<span class="dl-board">${escapeHtml(e.sub)}</span> `:''}${escapeHtml(e.label)}</span>
      <span class="dl-count">${e.total}</span>
    </div>`).join('');

  function tooltipFor(idx){
    const e = entries[idx];
    const rows = Object.entries(e.breakdown).sort((a,b)=>b[1]-a[1])
      .map(([k,n])=>`<div class="ctt-row"><span>${escapeHtml(k)}</span><b>${n}</b></div>`).join('');
    const title = e.sub ? `${e.sub} · ${e.label}` : e.label;
    return `<div class="ctt-title">${escapeHtml(title)} · ${e.total} open</div>${rows}`;
  }
  svg.querySelectorAll('[data-idx]').forEach(el=>{
    el.addEventListener('mousemove', ev=> showChartTooltip(tooltipFor(+el.dataset.idx), ev.clientX, ev.clientY));
    el.addEventListener('mouseleave', hideChartTooltip);
  });
  legend.querySelectorAll('[data-idx]').forEach(el=>{
    el.addEventListener('mousemove', ev=> showChartTooltip(tooltipFor(+el.dataset.idx), ev.clientX, ev.clientY));
    el.addEventListener('mouseleave', hideChartTooltip);
  });
}
document.getElementById('workloadToggle').addEventListener('click', e=>{
  const b = e.target.closest('.pill-toggle-btn'); if(!b) return;
  workloadMode = b.dataset.mode;
  document.querySelectorAll('#workloadToggle .pill-toggle-btn').forEach(x=>x.classList.toggle('active', x===b));
  renderWorkloadChart();
});
document.getElementById('statusBoardToggle').addEventListener('click', e=>{
  const b = e.target.closest('.pill-toggle-btn'); if(!b) return;
  statusBoardFilter = b.dataset.sboard;
  document.querySelectorAll('#statusBoardToggle .pill-toggle-btn').forEach(x=>x.classList.toggle('active', x===b));
  renderWorkloadChart();
});

/* ---------- movement log (data helpers + insights + modal) ---------- */
function fmtDateTime(iso){
  const d = new Date(iso);
  const day = d.getDate().toString().padStart(2,'0');
  const month = d.toLocaleString('en-US',{month:'short'});
  const hh = d.getHours().toString().padStart(2,'0');
  const mm = d.getMinutes().toString().padStart(2,'0');
  return `${day} ${month}, ${hh}:${mm}`;
}

function buildTransitionsList(tasks, board){
  const list = [];
  tasks.forEach(t=>{
    for(let i=1;i<t.history.length;i++){
      const h = t.history[i];
      const prev = t.history[i-1];
      list.push({
        task: t.title, board,
        from: prev.status, to: h.status,
        movedAt: h.enteredAt,
        timeInPrev: new Date(h.enteredAt) - new Date(prev.enteredAt)
      });
    }
  });
  return list;
}

function statusTextColor(list, id){
  const s = statusDef(list, id);
  return colorVars(s.color).tx;
}

function renderDashboardPatterns(pd, uxr){
  const pdMoves = buildTransitionsList(pd, 'PD');
  const uxrMoves = buildTransitionsList(uxr, 'UXR');
  const all = pdMoves.concat(uxrMoves);
  renderMoveInsights(pdMoves, uxrMoves, all);
}

function renderMoveInsights(pdMoves, uxrMoves, all){
  const el = document.getElementById('moveInsights');
  if(all.length===0){
    el.innerHTML = `<div class="d-empty">Nothing to spot yet — patterns will show up here once cards start moving.</div>`;
    return;
  }
  const backIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M19 12H5M11 6l-6 6 6 6"/></svg>`;
  const fwdIcon = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`;

  function tally(moves, order){
    const back = {}, fwd = {};
    moves.forEach(tr=>{
      const fi = order.indexOf(tr.from), ti = order.indexOf(tr.to);
      if(fi<0||ti<0) return;
      if(ti<fi) back[tr.to] = (back[tr.to]||0)+1;
      else if(ti>fi) fwd[tr.to] = (fwd[tr.to]||0)+1;
    });
    return {back, fwd};
  }
  const pdOrder = PD_STATUSES.map(s=>s.id);
  const uxrOrder = UXR_STATUSES.map(s=>s.id);
  const pdT = tally(pdMoves, pdOrder);
  const uxrT = tally(uxrMoves, uxrOrder);

  const entries = [];
  Object.entries(pdT.back).forEach(([status,n])=>entries.push({dir:'back', status, n, board:'PD'}));
  Object.entries(pdT.fwd).forEach(([status,n])=>entries.push({dir:'fwd', status, n, board:'PD'}));
  Object.entries(uxrT.back).forEach(([status,n])=>entries.push({dir:'back', status, n, board:'UXR'}));
  Object.entries(uxrT.fwd).forEach(([status,n])=>entries.push({dir:'fwd', status, n, board:'UXR'}));
  entries.sort((a,b)=>b.n-a.n);

  if(entries.length===0){
    el.innerHTML = `<div class="d-empty">No repeat back-and-forth yet — everything's moved forward once.</div>`;
    return;
  }
  el.innerHTML = entries.slice(0,6).map(e=>`
    <div class="insight-item ${e.dir==='back'?'back':'fwd'}">
      ${e.dir==='back'?backIcon:fwdIcon}
      <span>${e.board} tasks moved ${e.dir==='back'?'back':'forward'} to <b>${escapeHtml(e.status)}</b></span>
      <span class="icount">${e.n}x</span>
    </div>`).join('');
}

function buildMovementLogRows(board, tasks){
  const moves = buildTransitionsList(tasks, board.toUpperCase());
  moves.sort((a,b)=>new Date(b.movedAt)-new Date(a.movedAt));
  if(moves.length===0){
    return `<tr><td colspan="4"><div class="empty-state" style="padding:14px 0"><p>No moves recorded yet on this board. Drag a card and it'll show up here.</p></div></td></tr>`;
  }
  const statuses = board==='pd' ? PD_STATUSES : UXR_STATUSES;
  return moves.slice(0,50).map(tr=>`
    <tr>
      <td>${escapeHtml(tr.task)}</td>
      <td class="transition"><span style="color:${statusTextColor(statuses,tr.from)}">${escapeHtml(tr.from)}</span><span class="arrow">→</span><span style="color:${statusTextColor(statuses,tr.to)}">${escapeHtml(tr.to)}</span></td>
      <td class="movedcell">${fmtDateTime(tr.movedAt)}</td>
      <td class="durcell">${fmtDuration(tr.timeInPrev)}</td>
    </tr>`).join('');
}

function openMovementLogModal(board){
  const tasks = board==='pd' ? getAllPdTasks() : getAllUxrTasks();
  const title = board==='pd' ? 'PD movement log' : 'UXR movement log';
  document.getElementById('logModalBody').innerHTML = `
    <h3>⚡ ${title}</h3>
    <div class="card-sub" style="margin-bottom:14px">Every status transition recorded on this board, most recent first.</div>
    <div class="movelog-scroll" style="max-height:56vh">
      <table class="tstat movelog-table">
        <thead><tr><th>Task</th><th>From → To</th><th>Moved</th><th>Time in prev.</th></tr></thead>
        <tbody>${buildMovementLogRows(board, tasks)}</tbody>
      </table>
    </div>
    <div class="modal-actions"><button class="btn ghost" onclick="closeLogModal()">Close</button></div>
  `;
  document.getElementById('logModalBackdrop').classList.add('open');
}
function closeLogModal(){ document.getElementById('logModalBackdrop').classList.remove('open'); }
window.closeLogModal = closeLogModal;
document.getElementById('logModalBackdrop').addEventListener('click', e=>{ if(e.target.id==='logModalBackdrop') closeLogModal(); });

