/* ============================================================
   IA MIND MAP
   ============================================================ */
const PAGE_TYPES = [...new Set(DATA.pages.map(p=>p.type).filter(Boolean))].sort();

let mapFilters = { areas:new Set(), apps:new Set(), pageTypes:new Set(), statuses:new Set(), pd:new Set(), uxr:new Set() };
let mapZoom = 1;
let mapGraph = null;
let mapLayout = null;
let mapHighlightKey = null;
let mapOpenApps = new Set();
let mapOpenPages = new Set();
let mapOpenFeatures = new Set();

function taskAppNames(taskName){
  const base = DATA.pdTasks.find(t=>t.name===taskName || t.id===taskName);
  if(base && Array.isArray(base.apps) && base.apps.length) return base.apps;
  const custom = (pdBoardState.tasksCustom||[]).find(t=>t.title===taskName || t.id===taskName);
  if(custom && custom.appName) return [custom.appName];
  return [];
}
function pagesForApp(appName){
  return DATA.pages.filter(p=>(p.apps||[]).includes(appName)).map(p=>p.name);
}
function featuresForPage(pageName){
  return DATA.features.filter(f=>(f.surfaces||[]).includes(pageName)).map(f=>f.name);
}
function taskStatusAllowed(taskName){
  const st = pdTaskStatusFor(taskName) || 'Not Started';
  if(mapFilters.statuses.size && !mapFilters.statuses.has(st)) return false;
  if(mapFilters.pd.size){
    const pdTask = pdTaskByName[taskName];
    const names = (pdTask && pdTask.pd) || [];
    if(!names.some(n=>mapFilters.pd.has(n))) return false;
  }
  if(mapFilters.uxr.size){
    const uxrNames = getTaskUxrAssignees(taskName);
    if(!uxrNames.some(n=>mapFilters.uxr.has(n))) return false;
  }
  return true;
}
function closeFeatureBranch(featureName){
  mapOpenFeatures.delete(featureName);
}
function closePageBranch(pageName){
  mapOpenPages.delete(pageName);
  featuresForPage(pageName).forEach(closeFeatureBranch);
}
function closeAppBranch(appName){
  mapOpenApps.delete(appName);
  pagesForApp(appName).forEach(closePageBranch);
}
function openAppBranch(appName){
  mapOpenApps.add(appName);
  pagesForApp(appName).forEach(pageName=>{
    mapOpenPages.add(pageName);
    featuresForPage(pageName).forEach(featureName=>mapOpenFeatures.add(featureName));
  });
}
function openPageBranch(pageName){
  mapOpenPages.add(pageName);
  featuresForPage(pageName).forEach(featureName=>mapOpenFeatures.add(featureName));
}
function ensureMapNodeVisible(key){
  if(!key) return;
  const [type, name] = key.split(':');
  if(type==='app'){
    openAppBranch(name);
    return;
  }
  if(type==='page'){
    const page = pageByName[name];
    (page && page.apps || []).forEach(openAppBranch);
    openPageBranch(name);
    return;
  }
  if(type==='feature'){
    const feature = featureByName[name];
    if(!feature) return;
    DATA.pages.filter(p=>(feature.surfaces||[]).includes(p.name)).forEach(p=>{
      (p.apps||[]).forEach(openAppBranch);
      openPageBranch(p.name);
    });
    mapOpenFeatures.add(name);
    return;
  }
  if(type==='task'){
    taskAppNames(name).forEach(openAppBranch);
    const feature = DATA.features.find(f=>(f.tasks||[]).includes(name));
    if(feature){
      mapOpenFeatures.add(feature.name);
      DATA.pages
        .filter(p=>(feature.surfaces||[]).includes(p.name))
        .forEach(p=>openPageBranch(p.name));
    }
  }
}

function getTaskUxrAssignees(taskName){
  const pdTask = pdTaskByName[taskName] || pdTaskById[taskName];
  if(!pdTask) return [];
  const allUxr = getAllUxrTasks();
  const names = new Set();
  const related = allUxr.filter(x=>x.parentPdTask===pdTask.id || x.parentPdTask===pdTask.name || (pdTask.uxrTasks||[]).includes(x.title));
  related.forEach(t=>{
    const owners = splitPeople(t.productDesigner||t.assignee);
    if(owners.length){
      owners.forEach(n=>names.add(n));
    }
  });
  return [...names];
}

function computeVisibleGraph(){
  const apps = DATA.apps.filter(app=>{
    if(mapFilters.areas.size && !(app.productAreas||[]).some(a=>mapFilters.areas.has(a))) return false;
    if(mapFilters.apps.size && !mapFilters.apps.has(app.name)) return false;
    return true;
  });
  const appNames = new Set(apps.map(a=>a.name));
  const openAppNames = new Set([...mapOpenApps].filter(a=>appNames.has(a)));

  const pages = DATA.pages.filter(p=>{
    if(!(p.apps||[]).some(a=>appNames.has(a))) return false;
    if(!(p.apps||[]).some(a=>openAppNames.has(a))) return false;
    if(mapFilters.pageTypes.size && !mapFilters.pageTypes.has(p.type)) return false;
    return true;
  });
  const pageNames = new Set(pages.map(p=>p.name));
  const openPageNames = new Set([...mapOpenPages].filter(p=>pageNames.has(p)));

  const features = DATA.features.filter(f=>(f.surfaces||[]).some(s=>openPageNames.has(s)));
  const featureNames = new Set(features.map(f=>f.name));
  const openFeatureNames = new Set([...mapOpenFeatures].filter(f=>featureNames.has(f)));

  const tasks = [];
  features.forEach(f=>{
    if(!openFeatureNames.has(f.name)) return;
    (f.tasks||[]).forEach(tn=>{
      if(!taskStatusAllowed(tn)) return;
      tasks.push({name:tn, feature:f.name, status:pdTaskStatusFor(tn) || 'Not Started'});
    });
  });

  const appPageEdges = [];
  pages.forEach(p=>{ (p.apps||[]).forEach(a=>{ if(appNames.has(a)) appPageEdges.push([`app:${a}`, `page:${p.name}`]); }); });

  const pageFeatureEdges = [];
  features.forEach(f=>{ (f.surfaces||[]).forEach(s=>{ if(pageNames.has(s)) pageFeatureEdges.push([`page:${s}`, `feature:${f.name}`]); }); });

  const featureTaskEdges = tasks.map(t=>[`feature:${t.feature}`, `task:${t.name}`]);

  return {apps, pages, features, tasks, edges:[...appPageEdges, ...pageFeatureEdges, ...featureTaskEdges]};
}

function layoutGraph(g){
  const rowH = 42;
  const colW = 232;
  const colGap = 90;
  const xs = [50, 50+colW+colGap, 50+2*(colW+colGap), 50+3*(colW+colGap)];
  const positions = {};

  const sortedApps = [...g.apps].sort((a,b)=>a.name.localeCompare(b.name));
  const sortedPages = [...g.pages].sort((a,b)=>{
    const aApp=(a.apps&&a.apps[0])||''; const bApp=(b.apps&&b.apps[0])||'';
    return aApp.localeCompare(bApp) || a.name.localeCompare(b.name);
  });
  const sortedFeatures = [...g.features].sort((a,b)=>a.name.localeCompare(b.name));
  const sortedTasks = g.tasks;

  function place(list, x, keyFn){
    list.forEach((item,i)=>{ positions[keyFn(item)] = {x, y:56+i*rowH, w:colW, h:32}; });
  }
  place(sortedApps, xs[0], a=>`app:${a.name}`);
  place(sortedPages, xs[1], p=>`page:${p.name}`);
  place(sortedFeatures, xs[2], f=>`feature:${f.name}`);
  place(sortedTasks, xs[3], t=>`task:${t.name}`);

  const maxRows = Math.max(sortedApps.length, sortedPages.length, sortedFeatures.length, sortedTasks.length, 1);
  const height = 100 + maxRows*rowH;
  const width = xs[3]+colW+60;
  return {positions, height, width, sortedApps, sortedPages, sortedFeatures, sortedTasks};
}

function edgePath(a, b){
  const x1=a.x+a.w, y1=a.y+a.h/2, x2=b.x, y2=b.y+b.h/2;
  const mx = (x1+x2)/2;
  return `M ${x1} ${y1} C ${mx} ${y1}, ${mx} ${y2}, ${x2} ${y2}`;
}

function renderMindmap(){
  mapGraph = computeVisibleGraph();
  mapLayout = layoutGraph(mapGraph);
  const svg = document.getElementById('mindmapSvg');
  svg.setAttribute('width', mapLayout.width);
  svg.setAttribute('height', mapLayout.height);
  svg.setAttribute('viewBox', `0 0 ${mapLayout.width} ${mapLayout.height}`);

  let edgesHtml = '';
  mapGraph.edges.forEach(([a,b])=>{
    const pa = mapLayout.positions[a], pb = mapLayout.positions[b];
    if(!pa||!pb) return;
    edgesHtml += `<path class="medge" data-a="${escAttr(a)}" data-b="${escAttr(b)}" d="${edgePath(pa,pb)}"></path>`;
  });

  const visibleAppNames = new Set(mapGraph.apps.map(a=>a.name));
  const visiblePagesForCounts = DATA.pages.filter(p=>{
    if(!(p.apps||[]).some(a=>visibleAppNames.has(a))) return false;
    if(mapFilters.pageTypes.size && !mapFilters.pageTypes.has(p.type)) return false;
    return true;
  });
  const appChildCount = {};
  visibleAppNames.forEach(name=>{ appChildCount[name] = 0; });
  visiblePagesForCounts.forEach(p=>(p.apps||[]).forEach(a=>{ if(visibleAppNames.has(a)) appChildCount[a] = (appChildCount[a]||0) + 1; }));

  const pageChildCount = {};
  visiblePagesForCounts.forEach(p=>{ pageChildCount[p.name] = 0; });
  const visibleFeaturesForCounts = DATA.features.filter(f=>(f.surfaces||[]).some(s=>Object.prototype.hasOwnProperty.call(pageChildCount, s)));
  visibleFeaturesForCounts.forEach(f=>{
    (f.surfaces||[]).forEach(s=>{
      if(Object.prototype.hasOwnProperty.call(pageChildCount, s)) pageChildCount[s] += 1;
    });
  });

  const featureChildCount = {};
  visibleFeaturesForCounts.forEach(f=>{
    featureChildCount[f.name] = (f.tasks||[]).filter(taskStatusAllowed).length;
  });

  function chip(type, key, displayLabel, rawName, cls, count, expandable, style){
    const p = mapLayout.positions[key];
    if(!p) return '';
    return `<foreignObject x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}">
      <div xmlns="http://www.w3.org/1999/xhtml" class="mnode ${cls}" data-type="${type}" data-name="${escAttr(rawName)}" data-key="${escAttr(key)}" data-expandable="${expandable?'true':'false'}" style="${style||''}">
        <span class="mnode-label">${escapeHtml(displayLabel)}</span>
        ${count!=null?`<span class="mnode-count">${count}</span>`:''}
      </div>
    </foreignObject>`;
  }

  let nodesHtml = '';
  mapLayout.sortedApps.forEach(a=>{
    const childCount = appChildCount[a.name] || 0;
    const expandable = childCount > 0;
    const isOpen = mapOpenApps.has(a.name);
    const indicator = expandable ? (isOpen ? '\u25BE ' : '\u25B8 ') : '';
    nodesHtml += chip('app', `app:${a.name}`, indicator + a.name, a.name, 'mnode-app', childCount || null, expandable);
  });
  mapLayout.sortedPages.forEach(p=>{
    const childCount = pageChildCount[p.name] || 0;
    const expandable = childCount > 0;
    const isOpen = mapOpenPages.has(p.name);
    const indicator = expandable ? (isOpen ? '\u25BE ' : '\u25B8 ') : '';
    nodesHtml += chip('page', `page:${p.name}`, indicator + p.name, p.name, 'mnode-page', childCount || null, expandable);
  });
  mapLayout.sortedFeatures.forEach(f=>{
    const childCount = featureChildCount[f.name] || 0;
    const expandable = childCount > 0;
    const isOpen = mapOpenFeatures.has(f.name);
    const indicator = expandable ? (isOpen ? '\u25BE ' : '\u25B8 ') : '';
    nodesHtml += chip('feature', `feature:${f.name}`, indicator + f.name, f.name, 'mnode-feature', childCount || null, expandable);
  });
  mapLayout.sortedTasks.forEach(t=>{
    const s = statusDef(PD_STATUSES, t.status); const v = colorVars(s.color);
    nodesHtml += chip('task', `task:${t.name}`, t.name, t.name, 'mnode-task', null, false, `background:${v.bg};border-color:${v.bd};color:${v.tx}`);
  });

  svg.innerHTML = edgesHtml + nodesHtml;
  document.getElementById('mindmapEmpty').style.display = mapGraph.apps.length===0 ? 'flex' : 'none';
  applyMapHighlight();
}

function buildAdjacency(edges){
  const adj = {};
  edges.forEach(([a,b])=>{
    (adj[a] = adj[a]||new Set()).add(b);
    (adj[b] = adj[b]||new Set()).add(a);
  });
  return adj;
}
function connectedSet(startKey, edges){
  const adj = buildAdjacency(edges);
  const seen = new Set([startKey]);
  const queue = [startKey];
  while(queue.length){
    const cur = queue.shift();
    (adj[cur]||new Set()).forEach(n=>{ if(!seen.has(n)){ seen.add(n); queue.push(n); } });
  }
  return seen;
}
function applyMapHighlight(){
  const svg = document.getElementById('mindmapSvg');
  if(!mapHighlightKey){
    svg.querySelectorAll('.mnode').forEach(n=>n.classList.remove('dim','match'));
    svg.querySelectorAll('.medge').forEach(e=>e.classList.remove('dim','hl'));
    return;
  }
  const set = connectedSet(mapHighlightKey, mapGraph.edges);
  svg.querySelectorAll('.mnode').forEach(n=>{ n.classList.toggle('dim', !set.has(n.dataset.key)); });
  svg.querySelectorAll('.medge').forEach(e=>{
    const on = set.has(e.dataset.a) && set.has(e.dataset.b);
    e.classList.toggle('hl', on);
    e.classList.toggle('dim', !on);
  });
}

let mapDragging=false, mapWasDragged=false, mapDragStartX=0, mapDragStartY=0, mapScrollStartX=0, mapScrollStartY=0;
const mmWrap = document.getElementById('mindmapWrap');
mmWrap.addEventListener('mousedown', e=>{
  if(e.target.closest('.mnode')) return;
  mapDragging=true; mapWasDragged=false;
  mapDragStartX=e.clientX; mapDragStartY=e.clientY;
  mapScrollStartX=mmWrap.scrollLeft; mapScrollStartY=mmWrap.scrollTop;
  mmWrap.classList.add('grabbing');
});
window.addEventListener('mousemove', e=>{
  if(!mapDragging) return;
  const dx = e.clientX-mapDragStartX, dy=e.clientY-mapDragStartY;
  if(Math.abs(dx)>3||Math.abs(dy)>3) mapWasDragged=true;
  mmWrap.scrollLeft = mapScrollStartX - dx;
  mmWrap.scrollTop = mapScrollStartY - dy;
});
window.addEventListener('mouseup', ()=>{ mapDragging=false; mmWrap.classList.remove('grabbing'); });

mmWrap.addEventListener('click', e=>{
  if(mapWasDragged){ mapWasDragged=false; return; }
  const node = e.target.closest('.mnode');
  if(!node){ mapHighlightKey=null; applyMapHighlight(); return; }
  const key = node.dataset.key;
  const type = node.dataset.type, name = node.dataset.name;
  const expandable = node.dataset.expandable === 'true';
  if(type==='app'){
    if(expandable){
      if(mapOpenApps.has(name)) closeAppBranch(name);
      else openAppBranch(name);
      mapHighlightKey = null;
      renderMindmap();
      return;
    }
  }
  if(type==='page'){
    if(expandable){
      if(mapOpenPages.has(name)) closePageBranch(name);
      else openPageBranch(name);
      mapHighlightKey = null;
      renderMindmap();
      return;
    }
  }
  if(type==='feature'){
    if(expandable){
      if(mapOpenFeatures.has(name)) closeFeatureBranch(name);
      else mapOpenFeatures.add(name);
      mapHighlightKey = null;
      renderMindmap();
      return;
    }
  }
  if(mapHighlightKey===key){ mapHighlightKey=null; applyMapHighlight(); return; }
  mapHighlightKey = key;
  applyMapHighlight();
});

function setMapZoom(z){
  mapZoom = Math.min(2.2, Math.max(0.35, z));
  const svg = document.getElementById('mindmapSvg');
  svg.style.transform = `scale(${mapZoom})`;
  svg.style.transformOrigin = '0 0';
}
// Ctrl/Cmd + wheel = zoom (this is also how browsers report trackpad pinch gestures),
// plain wheel/two-finger scroll pans natively via the wrap's own overflow.
mmWrap.addEventListener('wheel', e=>{
  if(e.ctrlKey || e.metaKey){
    e.preventDefault();
    setMapZoom(mapZoom - e.deltaY*0.012);
  }
}, {passive:false});
mmWrap.addEventListener('dblclick', e=>{
  if(e.target.closest('.mnode')) return;
  setMapZoom(1);
});

/* ---------- filters panel ---------- */
function chipHtml(group, value){
  const active = mapFilters[group].has(value);
  return `<button class="mf-chip ${active?'active':''}" data-group="${group}" data-value="${escAttr(value)}">${escapeHtml(value)}</button>`;
}
function updateFilterCount(){
  const total = mapFilters.areas.size+mapFilters.apps.size+mapFilters.pageTypes.size+mapFilters.statuses.size+mapFilters.pd.size+mapFilters.uxr.size;
  const el = document.getElementById('mapFilterCount');
  el.textContent = total;
  el.style.display = total ? 'inline-block' : 'none';
}
function renderMapFilterPanel(){
  document.getElementById('mfAreas').innerHTML = DATA.productAreas.map(a=>chipHtml('areas', a.name)).join('');
  document.getElementById('mfApps').innerHTML = DATA.apps.map(a=>chipHtml('apps', a.name)).join('');
  document.getElementById('mfPageTypes').innerHTML = PAGE_TYPES.map(t=>chipHtml('pageTypes', t)).join('');
  document.getElementById('mfStatuses').innerHTML = PD_STATUSES.map(s=>chipHtml('statuses', s.id)).join('');

  const pdNames = new Set();
  getAllPdTasks().forEach(t=>splitPeople(t.productDesigner||t.assignee).forEach(n=>pdNames.add(n)));
  document.getElementById('mfPd').innerHTML = [...pdNames].sort().map(n=>chipHtml('pd', n)).join('');

  const uxrNames = new Set();
  getAllUxrTasks().forEach(t=>splitPeople(t.productDesigner||t.assignee).forEach(n=>uxrNames.add(n)));
  document.getElementById('mfUxr').innerHTML = [...uxrNames].sort().map(n=>chipHtml('uxr', n)).join('');

  updateFilterCount();
}
document.getElementById('mapFiltersBtn').addEventListener('click', ()=>{
  const panel = document.getElementById('mapFiltersPanel');
  panel.style.display = panel.style.display==='none' ? 'flex' : 'none';
});
document.getElementById('mapFiltersPanel').addEventListener('click', e=>{
  const chip = e.target.closest('.mf-chip'); if(!chip) return;
  const group = chip.dataset.group, value = chip.dataset.value;
  if(mapFilters[group].has(value)) mapFilters[group].delete(value); else mapFilters[group].add(value);
  chip.classList.toggle('active');
  updateFilterCount();
  renderMindmap();
});
document.getElementById('mfClearBtn').addEventListener('click', ()=>{
  Object.values(mapFilters).forEach(s=>s.clear());
  renderMapFilterPanel();
  renderMindmap();
});

/* ---------- search ---------- */
function mapSearchAll(query){
  const q = query.toLowerCase();
  const results = [];
  DATA.apps.forEach(a=>{ if(a.name.toLowerCase().includes(q)) results.push({type:'app', name:a.name, key:`app:${a.name}`}); });
  DATA.pages.forEach(p=>{ if(p.name.toLowerCase().includes(q)) results.push({type:'page', name:p.name, key:`page:${p.name}`}); });
  DATA.features.forEach(f=>{ if(f.name.toLowerCase().includes(q)) results.push({type:'feature', name:f.name, key:`feature:${f.name}`}); });
  DATA.pdTasks.forEach(t=>{ if(t.name.toLowerCase().includes(q)) results.push({type:'task', name:t.name, key:`task:${t.name}`}); });
  return results.slice(0,8);
}
const mapSearchInput = document.getElementById('mapSearch');
const mapSearchResultsEl = document.getElementById('mapSearchResults');
mapSearchInput.addEventListener('input', ()=>{
  const q = mapSearchInput.value.trim();
  if(q.length<2){ mapSearchResultsEl.classList.remove('open'); mapSearchResultsEl.innerHTML=''; return; }
  const results = mapSearchAll(q);
  mapSearchResultsEl.innerHTML = results.length===0
    ? `<div class="sr-empty">No matches</div>`
    : results.map(r=>`
      <div class="sr-item" data-key="${escAttr(r.key)}" data-type="${r.type}" data-name="${escAttr(r.name)}">
        <span class="sr-type ${r.type}">${r.type}</span>
        <span>${escapeHtml(r.name)}</span>
      </div>`).join('');
  mapSearchResultsEl.classList.add('open');
});
mapSearchResultsEl.addEventListener('click', e=>{
  const item = e.target.closest('.sr-item'); if(!item) return;
  goToMapNode(item.dataset.key);
  mapSearchResultsEl.classList.remove('open');
  mapSearchInput.value = item.dataset.name;
});
document.addEventListener('click', e=>{
  if(!e.target.closest('.map-search')) mapSearchResultsEl.classList.remove('open');
});

function goToMapNode(key){
  const hadFilters = mapFilters.areas.size||mapFilters.apps.size||mapFilters.pageTypes.size||mapFilters.statuses.size;
  if(hadFilters){
    Object.values(mapFilters).forEach(s=>s.clear());
    renderMapFilterPanel();
  }
  ensureMapNodeVisible(key);
  renderMindmap();
  const pos = mapLayout.positions[key];
  if(!pos) return;
  document.getElementById('mindmapWrap').scrollTo({
    left: pos.x - mmWrap.clientWidth/2 + pos.w/2,
    top: pos.y - mmWrap.clientHeight/2 + pos.h/2,
    behavior:'smooth'
  });
  mapHighlightKey = key;
  setTimeout(applyMapHighlight, 260);
}


/* ============================================================
   KANBAN BOARDS
   ============================================================ */
/* ============================================================
   BOARDS PAGE CONTROLLER (subtabs + filters)
   ============================================================ */
let activeBoard = 'pd';
let boardFilters = {app:'', pd:'', uxr:''};

const BOARD_COPY = {
  pd: {title:'PD task board', sub:'Product design tasks, tracked through the 8-stage design workflow. Drag a card between columns to update its status.'},
  uxr: {title:'UXR task board', sub:'Research tasks tracked through their own 5-stage workflow, linked back to the PD task that requested them.'}
};

function populateBoardFilters(){
  const appSel = document.getElementById('filterApp');
  const pdSel = document.getElementById('filterPd');
  const uxrSel = document.getElementById('filterUxr');

  const appNames = DATA.apps.map(a=>a.name).sort();
  appSel.innerHTML = `<option value="">All apps</option>` + appNames.map(n=>`<option value="${escAttr(n)}">${escapeHtml(n)}</option>`).join('');
  appSel.value = boardFilters.app;

  const pdMap = new Map();
  getAllPdTasks().forEach(t=>splitPeople(t.productDesigner||t.assignee).forEach(n=>{
    const key = peopleFilterKey(n);
    if(!key || pdMap.has(key)) return;
    pdMap.set(key, emailToDisplayName(n));
  }));
  pdSel.innerHTML = `<option value="">All designers</option>` + [...pdMap.entries()]
    .sort((a,b)=>a[1].localeCompare(b[1]))
    .map(([key,label])=>`<option value="${escAttr(key)}">${escapeHtml(label)}</option>`).join('');
  pdSel.value = boardFilters.pd;

  const uxrMap = new Map();
  getAllUxrTasks().forEach(t=>splitPeople(t.productDesigner||t.assignee).forEach(n=>{
    const key = peopleFilterKey(n);
    if(!key || uxrMap.has(key)) return;
    uxrMap.set(key, emailToDisplayName(n));
  }));
  uxrSel.innerHTML = `<option value="">All researchers</option>` + [...uxrMap.entries()]
    .sort((a,b)=>a[1].localeCompare(b[1]))
    .map(([key,label])=>`<option value="${escAttr(key)}">${escapeHtml(label)}</option>`).join('');
  uxrSel.value = boardFilters.uxr;
}

function renderBoardsPage(){
  populateBoardFilters();

  document.getElementById('boardSubtitle').textContent = BOARD_COPY[activeBoard].sub;
  renderSheetSyncBadge();
  renderBackendIndicator();
  document.querySelectorAll('#boardSubtabs .subtab-btn').forEach(b=>b.classList.toggle('active', b.dataset.board===activeBoard));
  document.getElementById('filterPdWrap').classList.toggle('disabled', activeBoard!=='pd');
  document.getElementById('filterUxrWrap').classList.toggle('disabled', activeBoard!=='uxr');

  renderBoard(activeBoard);
}

document.getElementById('boardSubtabs').addEventListener('click', e=>{
  const b = e.target.closest('.subtab-btn'); if(!b) return;
  activeBoard = b.dataset.board;
  renderBoardsPage();
});
document.getElementById('filterApp').addEventListener('change', e=>{ boardFilters.app = e.target.value; renderBoard(activeBoard); });
document.getElementById('filterPd').addEventListener('change', e=>{ boardFilters.pd = e.target.value; renderBoard(activeBoard); });
document.getElementById('filterUxr').addEventListener('change', e=>{ boardFilters.uxr = e.target.value; renderBoard(activeBoard); });
document.getElementById('clearFiltersBtn').addEventListener('click', ()=>{
  boardFilters = {app:'', pd:'', uxr:''};
  document.getElementById('filterApp').value = '';
  document.getElementById('filterPd').value = '';
  document.getElementById('filterUxr').value = '';
  renderBoard(activeBoard);
});
document.getElementById('viewLogBtn').addEventListener('click', ()=>{
  openMovementLogModal(activeBoard);
});

function uxrTaskAppName(t){
  const parent = getAllPdTasks().find(x=>x.id===t.parentPdTask || x.title===t.parentPdTask);
  return parent ? parent.appName : '';
}

function applyBoardFilters(board, tasks){
  return tasks.filter(t=>{
    if(boardFilters.app){
      const appName = board==='pd' ? t.appName : uxrTaskAppName(t);
      if(appName !== boardFilters.app) return false;
    }
    if(board==='pd' && boardFilters.pd){
      const names = splitPeople(t.productDesigner||t.assignee).map(peopleFilterKey);
      if(!names.includes(boardFilters.pd)) return false;
    }
    if(board==='uxr' && boardFilters.uxr){
      const names = splitPeople(t.productDesigner||t.assignee).map(peopleFilterKey);
      if(!names.includes(boardFilters.uxr)) return false;
    }
    return true;
  });
}

function renderBoard(board){
  const statuses = board==='pd' ? PD_STATUSES : UXR_STATUSES;
  const allTasks = board==='pd' ? getAllPdTasks() : getAllUxrTasks();
  const tasks = applyBoardFilters(board, allTasks);
  const el = document.getElementById('taskBoard');

  el.innerHTML = statuses.map(s=>{
    const v = colorVars(s.color);
    const colTasks = tasks.filter(t=>t.status===s.id);
    return `<div class="col" data-status="${escAttr(s.id)}" data-board="${board}">
      <div class="col-head">
        <div class="ctitle"><span class="cswatch" style="background:${v.bd}"></span>${escapeHtml(s.id)}</div>
        <div class="ccount">${colTasks.length}</div>
      </div>
      <div class="col-cards">${colTasks.map(t=>cardHtml(board, t)).join('')}</div>
      <button class="col-hover-add" data-add-status="${escAttr(s.id)}" data-add-board="${board}">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M12 5v14M5 12h14"/></svg>
        Add task
      </button>
    </div>`;
  }).join('');

  el.querySelectorAll('.kcard').forEach(card=>{
    card.addEventListener('dragstart', e=>{
      card.classList.add('dragging');
      e.dataTransfer.setData('text/plain', card.dataset.id);
      const restricted = card.dataset.statuses;
      if(restricted){
        const allowed = new Set(restricted.split('|'));
        el.querySelectorAll('.col').forEach(col=>{
          if(!allowed.has(col.dataset.status)) col.classList.add('drop-disabled');
        });
      }
    });
    card.addEventListener('dragend', ()=>{
      card.classList.remove('dragging');
      el.querySelectorAll('.col').forEach(col=>col.classList.remove('drop-disabled'));
    });
    card.addEventListener('click', ()=>{
      editTask(board, card.dataset.id);
    });
  });
  el.querySelectorAll('.col').forEach(col=>{
    col.addEventListener('dragover', e=>{
      if(col.classList.contains('drop-disabled')) return;
      e.preventDefault(); col.classList.add('dragover');
    });
    col.addEventListener('dragleave', ()=>col.classList.remove('dragover'));
    col.addEventListener('drop', e=>{
      if(col.classList.contains('drop-disabled')) return;
      e.preventDefault(); col.classList.remove('dragover');
      const id = e.dataTransfer.getData('text/plain');
      moveTask(col.dataset.board, id, col.dataset.status);
    });
  });
  el.querySelectorAll('.col-hover-add').forEach(btn=>{
    btn.addEventListener('click', e=>{
      e.stopPropagation();
      openAddModal(btn.dataset.addBoard, btn.dataset.addStatus);
    });
  });
}

function cardHtml(board, t){
  const overdue = isOverdue(t.estDate, t.status);
  const fullStatuses = (board==='pd' ? PD_STATUSES : UXR_STATUSES).map(s=>s.id);
  const allowed = t.allowedStatuses || normalizeAllowedStatuses(board, t.applicableStatuses || null);
  const statusDefs = (board==='pd' ? PD_STATUSES : UXR_STATUSES).filter(s=>
    allowed.includes(s.id) && s.id!=='Not Started' && s.id!=='Done'
  );
  const statusTrackTitle = statusDefs.length
    ? `Statuses: ${statusDefs.map(s=>s.id).join(' → ')}`
    : 'Statuses: none';
  const statusTrack = `<div class="kc-status-track" title="${escAttr(statusTrackTitle)}">${statusDefs.map(s=>{
    const v = colorVars(s.color);
    return `<span class="kc-status-dot" style="background:${v.bg};border-color:${v.bd}" aria-label="${escAttr(s.id)}"></span>`;
  }).join('')}</div>`;
  const statusesAttr = allowed.length===fullStatuses.length ? '' : ` data-statuses="${escAttr(allowed.join('|'))}"`;
  if(board==='pd'){
    const missingFields = Array.isArray(t.missingRequiredFields) ? t.missingRequiredFields : [];
    const hasSheetAlert = t.source==='sheet' && missingFields.length>0;
    const missingTitle = hasSheetAlert ? `Missing required: ${missingFields.join(', ')}` : '';
    return `<div class="kcard" draggable="true" data-id="${escAttr(t.id)}"${statusesAttr}>
      ${t.appName?`<div class="kc-app">${escapeHtml(t.appName)}</div>`:''}
      <div class="kc-title">${escapeHtml(t.title)}</div>
      ${hasSheetAlert ? `<div class="kc-alert-icon" title="${escAttr(missingTitle)}" aria-label="${escAttr(missingTitle)}">⚠</div>` : ''}
      ${statusTrack}
      <div class="kc-meta">
        <div class="kc-assignee">${personAvatarHtml(splitPeople(t.productDesigner||t.assignee)[0], peopleDisplayPrimary(t.productDesigner||t.assignee))}${escapeHtml(peopleDisplayPrimary(t.productDesigner||t.assignee))}</div>
        <div class="kc-date ${overdue?'overdue':''}">${t.estDate?fmtDate(t.estDate):'No date'}</div>
      </div>
      ${t.featureName?`<div class="kc-link-tag"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M9 6h11M9 12h11M9 18h11M5 6h.01M5 12h.01M5 18h.01"/></svg>${escapeHtml(t.featureName)}</div>`:''}
    </div>`;
  } else {
    return `<div class="kcard" draggable="true" data-id="${escAttr(t.id)}"${statusesAttr}>
      <div class="kc-app">Research</div>
      <div class="kc-title">${escapeHtml(t.title)}</div>
      ${statusTrack}
      <div class="kc-meta">
        <div class="kc-assignee">${personAvatarHtml(splitPeople(t.productDesigner||t.assignee)[0], peopleDisplayPrimary(t.productDesigner||t.assignee))}${escapeHtml(peopleDisplayPrimary(t.productDesigner||t.assignee))}</div>
        <div class="kc-date ${overdue?'overdue':''}">${t.estDate?fmtDate(t.estDate):'No date'}</div>
      </div>
      ${t.parentPdTask?`<div class="kc-link-tag"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M13 7l5 5-5 5M6 7l5 5-5 5"/></svg>${escapeHtml(t.parentPdTask)}</div>`:''}
    </div>`;
  }
}

function historyHtml(history){
  const now = Date.now();
  return history.map(h=>{
    const dur = h.exitedAt ? (new Date(h.exitedAt)-new Date(h.enteredAt)) : (now-new Date(h.enteredAt));
    return `<div class="history-row">
      <span>${h.isSeed?'Tracking started in':'Moved to'} <b>${escapeHtml(h.status)}</b></span>
      <span class="hdur">${h.exitedAt?fmtDuration(dur):'in progress · '+fmtDuration(dur)}</span>
    </div>`;
  }).reverse().join('');
}

function openPdCardDetail(id){
  const t = getAllPdTasks().find(x=>x.id===id); if(!t) return;
  const v = colorVars(statusDef(PD_STATUSES, t.status).color);
  const enabledOptional = getEnabledPdOptionalStatuses(t);
  const optionalMsg = enabledOptional.length===PD_CREATION_STATUSES.length
    ? ''
    : `Optional statuses enabled: ${enabledOptional.length ? enabledOptional.map(escapeHtml).join(', ') : 'none'}`;
  const missingFields = Array.isArray(t.missingRequiredFields) ? t.missingRequiredFields : [];
  const statusesThisTaskUses = (t.allowedStatuses || normalizeAllowedStatuses('pd', t.applicableStatuses || null));
  openDrawer(`
    <div class="d-type">PD Task${t.custom?' · custom':''}</div>
    <h2>${escapeHtml(t.title)}</h2>
    <div class="d-empty" style="margin-top:4px">${PD_REQUIRED_FIELD_HINT}</div>
    <div class="t-meta">
      ${t.appName?`<span class="tag acc">${escapeHtml(t.appName)}</span>`:''}
      <span class="tag">Product Designer: ${escapeHtml(peopleDisplayPrimary(t.productDesigner||t.assignee))}</span>
      ${t.startDate?`<span class="tag">Start ${fmtDate(t.startDate)}</span>`:''}
      ${t.estDate?`<span class="tag ${isOverdue(t.estDate,t.status)?'':''}" style="${isOverdue(t.estDate,t.status)?'background:var(--danger-soft);color:#A8332A':''}">Due ${fmtDate(t.estDate)}</span>`:''}
    </div>
    ${t.source==='sheet' && missingFields.length ? `<div class="d-section"><h5>Required fields missing in source sheet</h5><div class="d-empty">${escapeHtml(missingFields.join(', '))}</div></div>` : ''}
    <div class="d-section"><h5>Statuses this task uses</h5>
      <div class="status-checks">
        ${statusesThisTaskUses.map(st=>`<label class="status-check"><input type="checkbox" checked disabled> ${escapeHtml(st)}</label>`).join('')}
      </div>
    </div>
    <div class="d-section"><h5>People</h5>
      <div class="d-list">
        <div class="d-link-item" style="cursor:default"><span>Product Designer</span><span>${peopleListHtml(t.productDesigner||t.assignee)}</span></div>
        <div class="d-link-item" style="cursor:default"><span>Product Manager</span><span>${peopleListHtml(t.productManager)}</span></div>
        <div class="d-link-item" style="cursor:default"><span>Engineers</span><span>${peopleListHtml(t.engineers)}</span></div>
      </div>
    </div>
    <div class="d-section"><h5>Status</h5>
      <div class="status-select-row">
        ${PD_STATUSES.map(s=>{
          const vv = colorVars(s.color);
          const allowed = (t.allowedStatuses || normalizeAllowedStatuses('pd', t.applicableStatuses || null)).includes(s.id);
          return `<button class="status-pill ${s.id===t.status?'selected':''} ${allowed?'':'pill-disabled'}" style="background:${vv.bg};border-color:${vv.bd};color:${vv.tx}" ${allowed?`onclick="moveTask('pd','${escAttr(t.id)}','${escAttr(s.id)}')"`:'disabled'}>${escapeHtml(s.id)}</button>`;
        }).join('')}
      </div>
      ${optionalMsg?`<div class="d-empty" style="margin-top:6px">${optionalMsg}</div>`:''}
    </div>
    ${t.featureName?`<div class="d-section"><h5>Feature</h5><div class="d-list">${featureByName[t.featureName]?linkItemAndClose('feature',t.featureName):`<span class="d-empty">${escapeHtml(t.featureName)}</span>`}</div></div>`:''}
    ${t.pages && t.pages.length?`<div class="d-section"><h5>Pages</h5><div class="d-list">${t.pages.map(p=>pageByName[p]?linkItemAndClose('page',p):`<span class="d-empty">${escapeHtml(p)}</span>`).join('')}</div></div>`:''}
    ${t.files && t.files.length?`<div class="d-section"><h5>Design &amp; research files</h5><div class="d-list">${t.files.map(u=>`<a class="ext-link" href="${u}" target="_blank">${escapeHtml(u)}</a>`).join('<br>')}</div></div>`:''}
    <div class="d-section"><h5>Status history &amp; time tracking</h5>${historyHtml(t.history)}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="editTask('pd','${escAttr(t.id)}')">Edit task</button>
      <button class="btn ghost" onclick="deleteTask('pd','${escAttr(t.id)}')">Delete task</button>
    </div>
  `);
}
function openUxrCardDetail(id){
  const t = getAllUxrTasks().find(x=>x.id===id); if(!t) return;
  const parent = getAllPdTasks().find(x=>x.id===t.parentPdTask || x.title===t.parentPdTask);
  const parentLabel = parent ? parent.title : t.parentPdTask;
  const statusesThisTaskUses = (t.allowedStatuses || normalizeAllowedStatuses('uxr', t.applicableStatuses || null));
  openDrawer(`
    <div class="d-type">UXR Task${t.custom?' · custom':''}</div>
    <h2>${escapeHtml(t.title)}</h2>
    <div class="t-meta">
      <span class="tag">Product Designer: ${escapeHtml(peopleDisplayPrimary(t.productDesigner||t.assignee))}</span>
      ${t.estDate?`<span class="tag">Due ${fmtDate(t.estDate)}</span>`:''}
    </div>
    <div class="d-section"><h5>Statuses this task uses</h5>
      <div class="status-checks">
        ${statusesThisTaskUses.map(st=>`<label class="status-check"><input type="checkbox" checked disabled> ${escapeHtml(st)}</label>`).join('')}
      </div>
    </div>
    <div class="d-section"><h5>People</h5>
      <div class="d-list">
        <div class="d-link-item" style="cursor:default"><span>Product Designer</span><span>${peopleListHtml(t.productDesigner||t.assignee)}</span></div>
        <div class="d-link-item" style="cursor:default"><span>Product Manager</span><span>${peopleListHtml(t.productManager)}</span></div>
        <div class="d-link-item" style="cursor:default"><span>Engineers</span><span>${peopleListHtml(t.engineers)}</span></div>
      </div>
    </div>
    <div class="d-section"><h5>Status</h5>
      <div class="status-select-row">
        ${UXR_STATUSES.map(s=>{
          const vv = colorVars(s.color);
          const allowed = !t.applicableStatuses || t.applicableStatuses.includes(s.id);
          return `<button class="status-pill ${s.id===t.status?'selected':''} ${allowed?'':'pill-disabled'}" style="background:${vv.bg};border-color:${vv.bd};color:${vv.tx}" ${allowed?`onclick="moveTask('uxr','${escAttr(t.id)}','${escAttr(s.id)}')"`:'disabled'}>${escapeHtml(s.id)}</button>`;
        }).join('')}
      </div>
      ${t.applicableStatuses?`<div class="d-empty" style="margin-top:6px">This task only uses: ${t.applicableStatuses.map(escapeHtml).join(', ')}</div>`:''}
    </div>
    ${t.parentPdTask?`<div class="d-section"><h5>Requested by PD task</h5><div class="d-list"><div class="d-link-item" style="cursor:default"><span>${escapeHtml(parentLabel)}</span>${taskStatusChip(parent ? parent.id : t.parentPdTask)}</div></div></div>`:''}
    <div class="d-section"><h5>Status history &amp; time tracking</h5>${historyHtml(t.history)}</div>
    <div class="modal-actions">
      <button class="btn ghost" onclick="editTask('uxr','${escAttr(t.id)}')">Edit task</button>
      <button class="btn ghost" onclick="deleteTask('uxr','${escAttr(t.id)}')">Delete task</button>
    </div>
  `);
}
function linkItemAndClose(type,name){
  return `<div class="d-link-item" onclick="closeDrawer();setTimeout(()=>openDetail('${type}','${escAttr(name)}'),160)"><span>${escapeHtml(name)}</span></div>`;
}
async function deleteTask(board, id){
  const task = board==='pd' ? getAllPdTasks().find(x=>x.id===id) : getAllUxrTasks().find(x=>x.id===id);
  if(!task) return;
  if(!window.confirm(`Delete "${task.title}"? This cannot be undone.`)) return;
  if(board==='pd'){
    if(task.source==='sheet'){
      pdBoardState.deletedSheetKeys = Array.isArray(pdBoardState.deletedSheetKeys) ? pdBoardState.deletedSheetKeys : [];
      pdBoardState.deletedSheetStableKeys = Array.isArray(pdBoardState.deletedSheetStableKeys) ? pdBoardState.deletedSheetStableKeys : [];
      const full = (pdBoardState.tasksCustom||[]).find(t=>t.id===id);
      const key = full && full.sheetKey ? full.sheetKey : '';
      const stableKey = full && full.sheetStableKey ? full.sheetStableKey : sheetTaskKey(task.title, task.appName);
      if(key && !pdBoardState.deletedSheetKeys.includes(key)) pdBoardState.deletedSheetKeys.push(key);
      if(stableKey && !pdBoardState.deletedSheetStableKeys.includes(stableKey)) pdBoardState.deletedSheetStableKeys.push(stableKey);
    }
    pdBoardState.tasksCustom = (pdBoardState.tasksCustom||[]).filter(t=>t.id!==id);
    const baseIdx = DATA.pdTasks.findIndex(t=>(t.id||t.name)===id);
    if(baseIdx>=0){
      const base = DATA.pdTasks[baseIdx];
      DATA.pdTasks.splice(baseIdx,1);
      DATA.apps.forEach(a=>a.tasks=(a.tasks||[]).filter(n=>n!==base.name));
      DATA.features.forEach(f=>f.tasks=(f.tasks||[]).filter(n=>n!==base.name));
      DATA.pages.forEach(p=>p.tasks=(p.tasks||[]).filter(n=>n!==base.name));
      DATA.productAreas.forEach(a=>a.tasks=(a.tasks||[]).filter(n=>n!==base.name));
      const removedIds = (DATA.uxrSeedTasks||[]).filter(u=>u.parentPdTaskId===id).map(u=>u.id);
      DATA.uxrSeedTasks = (DATA.uxrSeedTasks||[]).filter(u=>u.parentPdTaskId!==id);
      removedIds.forEach(uid=>delete uxrBoardState.states[uid]);
    }
    delete pdBoardState.states[id];
    await storageSet('pd-board-state', pdBoardState);
  } else {
    uxrBoardState.tasksCustom = (uxrBoardState.tasksCustom||[]).filter(t=>t.id!==id);
    DATA.uxrSeedTasks = (DATA.uxrSeedTasks||[]).filter(t=>(t.id||t.name)!==id);
    delete uxrBoardState.states[id];
    await storageSet('uxr-board-state', uxrBoardState);
  }
  await savePortalData();
  closeDrawer();
  renderAll();
  showToast('Task deleted');
}
function editTask(board, id){
  const task = board==='pd' ? getAllPdTasks().find(x=>x.id===id) : getAllUxrTasks().find(x=>x.id===id);
  if(!task) return;
  const apps = DATA.apps.map(a=>`<option value="${escAttr(a.name)}" ${task.appName===a.name?'selected':''}>${escapeHtml(a.name)}</option>`).join('');
  const feats = DATA.features.map(f=>`<option value="${escAttr(f.name)}" ${task.featureName===f.name?'selected':''}>${escapeHtml(f.name)}</option>`).join('');
  const pdOpts = getAllPdTasks().map(t=>`<option value="${escAttr(t.id)}" ${(task.parentPdTask===t.id || task.parentPdTask===t.title)?'selected':''}>${escapeHtml(t.title)}</option>`).join('');
  const pdAllowedStatuses = task.allowedStatuses || normalizeAllowedStatuses('pd', task.applicableStatuses || null);
  const editableStatuses = (board==='pd' ? PD_STATUSES.map(s=>s.id).filter(id=>pdAllowedStatuses.includes(id)) : UXR_STATUSES.map(s=>s.id));
  const statusOptions = editableStatuses.map(st=>`<option value="${escAttr(st)}" ${st===task.status?'selected':''}>${escapeHtml(st)}</option>`).join('');
  const linkedFeatures = board==='pd' ? DATA.features.filter(f=>(f.tasks||[]).includes(task.title)) : [];
  const directPages = board==='pd' ? DATA.pages.filter(p=>(p.tasks||[]).includes(task.title)) : [];
  const viaFeaturePages = board==='pd' && task.featureName ? DATA.pages.filter(p=>(p.features||[]).includes(task.featureName)) : [];
  const pageLinkMap = {};
  directPages.forEach(p=>{ pageLinkMap[p.name] = ['direct task link']; });
  viaFeaturePages.forEach(p=>{
    pageLinkMap[p.name] = pageLinkMap[p.name] || [];
    if(!pageLinkMap[p.name].includes('via feature "'+task.featureName+'"')) pageLinkMap[p.name].push('via feature "'+task.featureName+'"');
  });
  const linkedPages = Object.keys(pageLinkMap).sort();
  const linkedSummary = board==='pd'
    ? `<div class="field"><label>Linked items</label>
         <div class="d-empty">${linkedFeatures.length} feature(s) · ${linkedPages.length} page(s)</div>
         <button id="et_links_toggle" class="btn ghost small" type="button" style="padding:0;border:none;background:none;color:var(--accent)">See all</button>
         <div id="et_links_detail" style="display:none;margin-top:8px">
           <div class="d-empty"><b>Features</b></div>
           ${linkedFeatures.length ? `<div class="d-list">${linkedFeatures.map(f=>`<div class="d-link-item" style="cursor:default"><span>${escapeHtml(f.name)}</span><span class="d-empty">direct task link</span></div>`).join('')}</div>` : '<div class="d-empty">No linked features</div>'}
           <div class="d-empty" style="margin-top:8px"><b>Pages</b></div>
           ${linkedPages.length ? `<div class="d-list">${linkedPages.map(name=>`<div class="d-link-item" style="cursor:default"><span>${escapeHtml(name)}</span><span class="d-empty">${escapeHtml(pageLinkMap[name].join(' + '))}</span></div>`).join('')}</div>` : '<div class="d-empty">No linked pages</div>'}
         </div>
       </div>`
    : '';
  openModal(`
    <h3>Edit ${board.toUpperCase()} task</h3>
    ${board==='pd' ? `<div class="d-empty" style="margin-bottom:8px">${PD_REQUIRED_FIELD_HINT}</div>` : ''}
    <div class="field"><label>Task name</label><input id="et_title" value="${escAttr(task.title)}"></div>
    ${board==='pd'
      ? `<div class="field"><label>App *</label><select id="et_app"><option value="">—</option>${apps}</select></div><div class="field"><label>Feature</label><select id="et_feature"><option value="">—</option>${feats}</select></div>`
      : `<div class="field"><label>Linked PD task</label><select id="et_parent"><option value="">—</option>${pdOpts}</select></div>`
    }
    <div class="field"><label>Product Designer${board==='pd' ? ' *' : ''}</label><input id="et_designer" value="${escAttr(task.productDesigner||task.assignee||'')}" placeholder="name@totersapp.com, ..."></div>
    <div class="field"><label>Product Manager${board==='pd' ? ' *' : ''}</label><input id="et_pm" value="${escAttr(task.productManager||'')}" placeholder="name@totersapp.com, ..."></div>
    <div class="field"><label>Engineers</label><input id="et_eng" value="${escAttr(task.engineers||'')}" placeholder="name@totersapp.com, ..."></div>
    <div class="field"><label>Expected start date</label><input id="et_start_date" type="date" value="${escAttr(task.startDate||'')}"></div>
    <div class="field"><label>Estimated date</label><input id="et_date" type="date" value="${escAttr(task.estDate||'')}"></div>
    <div class="field"><label>Status</label><select id="et_status">${statusOptions}</select></div>
    ${linkedSummary}
    <div class="modal-actions">
      <button class="btn ghost" id="et_delete" type="button">Delete task</button>
      <button class="btn ghost" onclick="closeModal()">Cancel</button>
      <button class="btn primary" id="et_save">Save</button>
    </div>
  `);
  enablePeopleFieldAutocomplete(['et_designer','et_pm','et_eng']);
  const linksToggle = document.getElementById('et_links_toggle');
  if(linksToggle){
    linksToggle.addEventListener('click', ()=>{
      const detail = document.getElementById('et_links_detail');
      const open = detail.style.display!=='none';
      detail.style.display = open ? 'none' : 'block';
      linksToggle.textContent = open ? 'See all' : 'Hide breakdown';
    });
  }
  document.getElementById('et_delete').addEventListener('click', async ()=>{
    closeModal();
    await deleteTask(board, id);
  });
  document.getElementById('et_save').addEventListener('click', async ()=>{
    const title = document.getElementById('et_title').value.trim();
    if(!title){ showToast('Task name is required'); return; }
    const status = document.getElementById('et_status').value;
    const pdPeople = parseTotersPeople(document.getElementById('et_designer').value.trim());
    const pmPeople = parseTotersPeople(document.getElementById('et_pm').value.trim());
    const engPeople = parseTotersPeople(document.getElementById('et_eng').value.trim());
    if(!pdPeople.ok || !pmPeople.ok || !engPeople.ok){
      const invalid = [...pdPeople.invalid, ...pmPeople.invalid, ...engPeople.invalid];
      showToast(`Use @${TOTERS_EMAIL_DOMAIN} emails only: ${invalid.join(', ')}`);
      return;
    }
    const productDesigner = pdPeople.list.join(', ');
    const productManager = pmPeople.list.join(', ');
    const engineers = engPeople.list.join(', ');
    if(board==='pd'){
      if(!document.getElementById('et_app').value){ showToast('Application is required'); return; }
      if(!productDesigner){ showToast('Product Designer is required'); return; }
      if(!productManager){ showToast('Product Manager is required'); return; }
      const base = DATA.pdTasks.find(t=>(t.id||t.name)===id);
      const custom = (pdBoardState.tasksCustom||[]).find(t=>t.id===id);
      if(base){
        const oldName = base.name;
        base.name = title;
        base.apps = document.getElementById('et_app').value ? [document.getElementById('et_app').value] : [];
        base.feature = document.getElementById('et_feature').value;
        base.productDesigner = productDesigner;
        base.productManager = productManager;
        base.engineers = engineers;
        base.pd = productDesigner ? productDesigner.split(',').map(x=>x.trim()).filter(Boolean) : [];
        base.startDate = document.getElementById('et_start_date').value;
        base.estDate = document.getElementById('et_date').value;
        DATA.apps.forEach(a=>replaceInArray(a.tasks, oldName, base.name));
        DATA.features.forEach(f=>replaceInArray(f.tasks, oldName, base.name));
        DATA.pages.forEach(p=>replaceInArray(p.tasks, oldName, base.name));
        DATA.productAreas.forEach(a=>replaceInArray(a.tasks, oldName, base.name));
      }
      if(custom){
        custom.title = title;
        custom.appName = document.getElementById('et_app').value;
        custom.featureName = document.getElementById('et_feature').value;
        custom.productDesigner = productDesigner;
        custom.productManager = productManager;
        custom.engineers = engineers;
        custom.assignee = productDesigner || 'Unassigned';
        custom.startDate = document.getElementById('et_start_date').value;
        custom.estDate = document.getElementById('et_date').value;
        if(custom.source==='sheet'){
          custom.missingRequiredFields = missingRequiredFieldsForSheetTask({
            title: custom.title,
            appName: custom.appName,
            productDesigner,
            productManager,
            startDate: custom.startDate,
            estDate: custom.estDate
          });
        }
      }
      syncTaskStatus(pdBoardState, id, status);
      await storageSet('pd-board-state', pdBoardState);
    } else {
      const base = (DATA.uxrSeedTasks||[]).find(t=>(t.id||t.name)===id);
      const custom = (uxrBoardState.tasksCustom||[]).find(t=>t.id===id);
      if(base){
        base.name = title;
        base.parentPdTaskId = document.getElementById('et_parent').value;
        base.productDesigner = productDesigner;
        base.productManager = productManager;
        base.engineers = engineers;
        base.assignee = productDesigner || 'Unassigned';
        base.estDate = document.getElementById('et_date').value;
      }
      if(custom){
        custom.title = title;
        custom.parentPdTask = document.getElementById('et_parent').value;
        custom.productDesigner = productDesigner;
        custom.productManager = productManager;
        custom.engineers = engineers;
        custom.assignee = productDesigner || 'Unassigned';
        custom.estDate = document.getElementById('et_date').value;
      }
      syncTaskStatus(uxrBoardState, id, status);
      await storageSet('uxr-board-state', uxrBoardState);
    }
    await savePortalData();
    closeModal();
    closeDrawer();
    renderAll();
    showToast('Task updated');
  });
}
