/* ============================================================
   AI ASSISTANT (floating widget + standalone page)
   Uses the live Anthropic API — only works while this file is
   running inside Claude.ai's artifact preview.
   ============================================================ */
const SPARKLE_SVG = '<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 1 15 9 23 12 15 15 12 23 9 15 1 12 9 9Z"/><path d="M19 3 20.5 5 19 7 17.5 5Z"/></svg>';

let chatConversations = [];
let chatWorkflows = [];
let currentConversationId = null;
let chatBusy = false;

async function loadChatData(){
  const conv = await personalGet('chat-conversations');
  chatConversations = Array.isArray(conv) ? conv : [];
  const wf = await personalGet('chat-workflows');
  chatWorkflows = Array.isArray(wf) ? wf : [];
  if(chatConversations.length){
    chatConversations.sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));
    currentConversationId = chatConversations[0].id;
  } else {
    startNewConversation(false);
  }
}
async function saveChatConversations(){ await personalSet('chat-conversations', chatConversations); }
async function saveChatWorkflows(){ await personalSet('chat-workflows', chatWorkflows); }

function getCurrentConversation(){
  return chatConversations.find(c=>c.id===currentConversationId);
}
function startNewConversation(shouldRender){
  const conv = {id: uid('chat'), title:'New chat', messages:[], createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()};
  chatConversations.unshift(conv);
  currentConversationId = conv.id;
  saveChatConversations();
  if(shouldRender!==false) renderAllChatUI();
}

function buildAssistantContext(){
  const pd = getAllPdTasks();
  const uxr = getAllUxrTasks();
  const overdueTasks = pd.filter(t=>isOverdue(t.estDate,t.status)).concat(uxr.filter(t=>isOverdue(t.estDate,t.status)));

  const backtrackList = [];
  const pdOrder = PD_STATUSES.map(s=>s.id);
  const uxrOrder = UXR_STATUSES.map(s=>s.id);
  function collectBacktrack(tasks, order, board){
    tasks.forEach(t=>{
      for(let i=1;i<t.history.length;i++){
        const prev=t.history[i-1], h=t.history[i];
        const fi=order.indexOf(prev.status), ti=order.indexOf(h.status);
        if(fi>=0 && ti>=0 && ti<fi){ backtrackList.push(`${board} "${t.title}" moved back from ${prev.status} to ${h.status}`); break; }
      }
    });
  }
  collectBacktrack(pd, pdOrder, 'PD');
  collectBacktrack(uxr, uxrOrder, 'UXR');

  const appBreakdown = DATA.apps.map(app=>{
    const appPd = pd.filter(t=>t.appName===app.name);
    const appUxr = uxr.filter(t=>uxrTaskAppName(t)===app.name);
    const inProg = appPd.filter(t=>t.status!=='Done' && t.status!=='Not Started').length;
    return `${app.name}: ${appPd.length+appUxr.length} tasks (${inProg} in progress)`;
  }).join('\n');

  const workload = computeWorkload(pd, uxr);
  const workloadStr = Object.entries(workload).map(([n,d])=>`${n}: ${d.total} open tasks`).join('\n') || 'none assigned';

  return `You are embedded inside "Design Ops Portal", an internal tool for the Toters product design team. Answer using ONLY the live data below — never invent tasks, apps, numbers, or people that aren't listed here. If something isn't in the data, say so plainly.

PORTAL STRUCTURE (pages you can send the user to):
- dashboard: KPIs, patterns/activity log, task status distribution, avg. time in status, workload distribution
- database: browsable Apps / Features / Pages / Product Areas
- iamap: a visual mind map of App -> Page -> Feature -> Task, with search and filters
- boards: PD and UXR kanban task boards with movement logs
- ai: this chat's own standalone page (don't navigate here, the user is already using chat)

APPS (${DATA.apps.length}):
${DATA.apps.map(a=>`- ${a.name}: ${a.description||'no description'} | product areas: ${(a.productAreas||[]).join(', ')||'none'} | ${a.surfaces.length} pages, ${a.features.length} features`).join('\n')}

FEATURES (${DATA.features.length}):
${DATA.features.map(f=>`- ${f.name}: apps=${(f.apps||[]).join(', ')||'—'} | pages=${(f.surfaces||[]).join(', ')||'—'} | PD=${(f.pd||[]).join(', ')||'—'} | tasks=${(f.tasks||[]).join(', ')||'—'}`).join('\n')}

PRODUCT AREAS: ${DATA.productAreas.map(a=>a.name).join(', ')}

PD TASKS — live status (${pd.length} total):
${pd.map(t=>`- "${t.title}" | app=${t.appName||'—'} | feature=${t.featureName||'—'} | status=${t.status} | productDesigner=${t.productDesigner||t.assignee} | due=${t.estDate||'—'}${isOverdue(t.estDate,t.status)?' [OVERDUE]':''}`).join('\n') || 'none'}

UXR TASKS — live status (${uxr.length} total):
${uxr.map(t=>`- "${t.title}" | linked PD task=${t.parentPdTask||'—'} | status=${t.status} | productDesigner=${t.productDesigner||t.assignee}`).join('\n') || 'none'}

VALID PD STATUSES: ${pdOrder.join(', ')}
VALID UXR STATUSES: ${uxrOrder.join(', ')}

COMPUTED INSIGHTS:
- Overdue tasks: ${overdueTasks.length===0?'none':overdueTasks.map(t=>t.title).join(', ')}
- Backtracking (sent back to an earlier status at some point): ${backtrackList.length===0?'none':'\n  '+backtrackList.join('\n  ')}
- Tasks per app:\n${appBreakdown}
- Workload per person (open tasks):\n${workloadStr}

NAVIGATION: when it would help, include exactly ONE of these tags naturally at the end of a sentence in your reply, and the portal will jump the user there automatically: [[nav:dashboard]] [[nav:database]] [[nav:iamap]] [[nav:boards]] — or to open a specific item's detail panel: [[open:app:ExactAppName]] [[open:feature:ExactFeatureName]] [[open:page:ExactPageName]] [[open:task:ExactTaskTitle]] (names must match the data above exactly, emoji included for app names).

ACTIONS: if the user clearly asks you to create a new task, first briefly confirm what you're creating in plain language, then include exactly one tag at the very end: [[action:addPdTask:{"title":"...","appName":"...","featureName":"...","productDesigner":"...","productManager":"...","engineers":"...","estDate":"YYYY-MM-DD","status":"..."}]] for a PD task, or [[action:addUxrTask:{"title":"...","parentPdTask":"...","productDesigner":"...","productManager":"...","engineers":"...","estDate":"YYYY-MM-DD","status":"..."}]] for a UXR task. status must exactly match one of the VALID statuses listed above for that board. Use "" for any field you don't know. Only use an action tag when the user is clearly asking you to create something — never for questions.

Never use more than one tag (nav/open/action) per reply, and never explain the tag syntax to the user.

STYLE: Concise (2-5 sentences unless a list is genuinely clearer). Reference specific task/app names from the data. When asked for insights or recommendations, ground them in the computed insights above and be direct about what's worth attention. Plain text only — no markdown formatting like ** or # or backticks, since this chat doesn't render markdown.`;
}

function messageBubbleHtml(m){
  if(m.role==='user') return `<div class="chat-msg user">${escapeHtml(m.text)}</div>`;
  let html = `<div class="chat-msg assistant">${escapeHtml(m.text)}</div>`;
  if(m.navAction){
    const label = m.navAction.type==='nav' ? `Opened ${m.navAction.target}`
      : m.navAction.type==='open' ? `Opened ${m.navAction.value}`
      : `Created task: ${m.navAction.value}`;
    html += `<div class="chat-nav-chip">\u21B3 ${escapeHtml(label)}</div>`;
  }
  return html;
}
function emptyHintHtml(forPage){
  if(forPage){
    return `<div class="ai-empty-hint"><div class="ai-empty-icon">${SPARKLE_SVG}</div><h2>Design Ops Assistant</h2><p>Ask about tasks, apps, or patterns — or run a workflow from the sidebar.</p></div>`;
  }
  return `<div class="chat-empty-hint">Ask about tasks, apps, or patterns — I can also jump you straight to the right page or item.</div>`;
}

function renderConversationMessages(){
  const conv = getCurrentConversation();
  const msgs = conv ? conv.messages : [];
  const html = msgs.map(messageBubbleHtml).join('');

  const floatEl = document.getElementById('chatMessages');
  if(floatEl){
    floatEl.innerHTML = msgs.length ? html : emptyHintHtml(false);
    floatEl.scrollTop = floatEl.scrollHeight;
  }
  const sugg = document.getElementById('chatSuggestions');
  if(sugg) sugg.style.display = msgs.length ? 'none' : 'flex';

  const pageEl = document.getElementById('aiPageMessages');
  const pageScroll = document.getElementById('aiPageMessagesScroll');
  if(pageEl){
    pageEl.innerHTML = msgs.length ? html : emptyHintHtml(true);
    if(pageScroll) pageScroll.classList.toggle('is-empty', msgs.length===0);
    if(pageScroll) pageScroll.scrollTop = pageScroll.scrollHeight;
  }
}
function renderHistoryList(){
  const el = document.getElementById('aiHistoryList');
  if(!el) return;
  if(chatConversations.length===0){
    el.innerHTML = `<div class="ai-side-empty">No past chats yet</div>`;
    return;
  }
  el.innerHTML = [...chatConversations].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).map(c=>`
    <div class="ai-side-item history-item ${c.id===currentConversationId?'active':''}" data-id="${escAttr(c.id)}">
      <span class="hi-title">${escapeHtml(c.title||'New chat')}</span>
      <button class="hi-delete" data-del="${escAttr(c.id)}" title="Delete">\u00D7</button>
    </div>`).join('');
}
function renderWorkflowList(){
  const el = document.getElementById('aiWorkflowList');
  if(!el) return;
  if(chatWorkflows.length===0){
    el.innerHTML = `<div class="ai-side-empty">No workflows yet</div>`;
    return;
  }
  el.innerHTML = chatWorkflows.map(w=>`
    <div class="ai-side-item workflow-item" data-run="${escAttr(w.id)}">
      <span class="hi-title">${escapeHtml(w.name)}</span>
      <button class="hi-delete" data-delwf="${escAttr(w.id)}" title="Delete">\u00D7</button>
    </div>`).join('');
}
function renderAllChatUI(){
  renderConversationMessages();
  renderHistoryList();
  renderWorkflowList();
}

function appendTypingIndicators(){
  const els = [];
  ['chatMessages','aiPageMessages'].forEach(id=>{
    const container = document.getElementById(id);
    if(!container) return;
    const div = document.createElement('div');
    div.className = 'chat-typing';
    div.innerHTML = '<span></span><span></span><span></span>';
    container.appendChild(div);
    const scroller = id==='aiPageMessages' ? document.getElementById('aiPageMessagesScroll') : container;
    if(scroller) scroller.scrollTop = scroller.scrollHeight;
    els.push(div);
  });
  return els;
}
function removeTypingIndicators(els){ els.forEach(el=>el.remove()); }
function setChatSendingState(busy){
  const b1 = document.getElementById('chatSendBtn'); if(b1) b1.disabled = busy;
  const b2 = document.getElementById('aiPageSendBtn'); if(b2) b2.disabled = busy;
}

function executeChatNav(type, target, value){
  if(type==='nav'){
    const btn = document.querySelector(`.tab-btn[data-page="${target}"]`);
    if(btn) btn.click();
  } else if(type==='open'){
    if(target==='app'||target==='feature'||target==='page') openDetail(target, value);
    else if(target==='task') openPdCardDetail(value);
    document.getElementById('chatPanel').classList.remove('open');
  }
}

async function sendChatMessage(text){
  if(!text || chatBusy) return;
  const conv = getCurrentConversation();
  if(!conv) return;
  chatBusy = true;
  setChatSendingState(true);

  conv.messages.push({role:'user', text});
  if(conv.title==='New chat') conv.title = text.length>42 ? text.slice(0,42)+'\u2026' : text;
  conv.updatedAt = new Date().toISOString();
  renderAllChatUI();
  const typingEls = appendTypingIndicators();

  try{
    const systemPrompt = buildAssistantContext();
    const apiMessages = conv.messages.map(m=>({role:m.role, content:m.text}));
    const response = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1000,
        system: systemPrompt,
        messages: apiMessages
      })
    });
    let data;
    try{ data = await response.json(); } catch(e){ data = null; }
    if(!response.ok){
      const apiErr = (data && data.error && data.error.message) ? data.error.message : `HTTP ${response.status}`;
      throw new Error(apiErr);
    }
    const textBlocks = ((data && data.content) || []).filter(b=>b.type==='text').map(b=>b.text);
    let reply = textBlocks.join('\n').trim() || "I couldn't put together a response there — try rephrasing?";

    const navMatch = reply.match(/\[\[(nav|open):([a-zA-Z]+)(?::([^\]]+))?\]\]/);
    const actionMatch = reply.match(/\[\[action:(addPdTask|addUxrTask):(\{[\s\S]*?\})\]\]/);
    reply = reply.replace(/\[\[(nav|open):[a-zA-Z]+(?::[^\]]+)?\]\]/g, '').replace(/\[\[action:[a-zA-Z]+:\{[\s\S]*?\}\]\]/g, '').trim();

    removeTypingIndicators(typingEls);
    let navAction = navMatch ? {type:navMatch[1], target:navMatch[2], value:navMatch[3]} : null;

    if(actionMatch){
      try{
        const payload = JSON.parse(actionMatch[2]);
        if(actionMatch[1]==='addPdTask') await addPdTask(payload);
        else await addUxrTask(payload);
        navAction = {type:'action', value: payload.title || 'task'};
      }catch(e){
        console.error('chat action failed', e);
        reply += "\n\n(Couldn't complete that automatically — try the New Task button instead.)";
      }
    }

    conv.messages.push({role:'assistant', text:reply, navAction});
    conv.updatedAt = new Date().toISOString();
    saveChatConversations();
    renderAllChatUI();
    if(navAction && navAction.type!=='action') executeChatNav(navAction.type, navAction.target, navAction.value);
  }catch(e){
    removeTypingIndicators(typingEls);
    conv.messages.push({role:'assistant', text: `Something went wrong reaching the assistant: ${e.message||'unknown error'}. This only works while the portal is running inside Claude.ai's artifact preview — it won't work if the file is opened directly or hosted elsewhere.`});
    conv.updatedAt = new Date().toISOString();
    saveChatConversations();
    renderAllChatUI();
    console.error('chat error', e);
  }finally{
    chatBusy = false;
    setChatSendingState(false);
  }
}

function autoGrowInput(ta){
  ta.style.height = 'auto';
  ta.style.height = Math.min(120, ta.scrollHeight)+'px';
}

