document.getElementById('aiHistoryList').addEventListener('click', e=>{
  const del = e.target.closest('[data-del]');
  if(del){
    const id = del.dataset.del;
    chatConversations = chatConversations.filter(c=>c.id!==id);
    if(currentConversationId===id){
      if(chatConversations.length) currentConversationId = chatConversations[0].id;
      else { startNewConversation(false); }
    }
    saveChatConversations();
    renderAllChatUI();
    return;
  }
  const item = e.target.closest('.history-item');
  if(item){ currentConversationId = item.dataset.id; renderAllChatUI(); }
});

